// components/my-portfolios/EditSquareProfileSidebar.tsx
"use client"

import { useEffect, useMemo, useRef, useState } from "react"
import ArrowLeft from "@/components/icons/ArrowLeft"
import ImageIcon from "@/components/icons/ImageIcon"
import SecondaryButton from "@/components/buttons/SecondaryButton"

import BrushIcon from "@/components/icons/BrushIcon"
import LocationIcon from "@/components/icons/LocationIcon"
import OpenTabIcon from "@/components/icons/OpenTabIcon"
import LinkIcon from "@/components/icons/LinkIcon"
import PlusIcon from "@/components/icons/PlusIcon"

import Tag from "@/components/onboarding/Tag"

type Props = {
  backHref: string

  // colors (optional)
  bannerColor?: string
  backgroundColor?: string
  onChangeBannerColor?: (hex: string) => void
  onChangeBackgroundColor?: (hex: string) => void

  // profile image
  profileImageUrl?: string
  onChangeProfileImage?: (file: File, objectUrl: string) => void

  // text fields
  businessName?: string
  displayName?: string
  onChangeBusinessName?: (val: string) => void
  onChangeDisplayName?: (val: string) => void

  // links row
  showAddLink?: boolean
  onAddLinkClick?: () => void

  // merch tag
  showMerchTag?: boolean
  onMerchClick?: () => void

  // previous vends
  previousVends?: string[]
  onChangePreviousVends?: (vals: string[]) => void

  // location/email
  locationText?: string
  email?: string
  onChangeLocationText?: (val: string) => void
  onChangeEmail?: (val: string) => void

  // bottom actions
  publishLabel?: string
  onPublish?: () => void
  onOpenPreview?: () => void
}

function parseEventLine(line: string): { title: string; year?: string } {
  const trimmed = (line || "").trim()
  if (!trimmed) return { title: "" }

  // Match a trailing 4-digit year optionally wrapped in parentheses
  // Examples: "Vended Event 2026", "Vended Event (2026)"
  const m = trimmed.match(/^(.*?)(?:\s*\(?(\d{4})\)?)\s*$/)
  if (!m) return { title: trimmed }

  const maybeTitle = (m[1] ?? "").trim()
  const maybeYear = m[2]

  // Only treat as year if there is *some* title before it
  if (maybeYear && maybeTitle.length > 0) {
    return { title: maybeTitle, year: maybeYear }
  }
  return { title: trimmed }
}

export default function EditSquareProfileSidebar({
  backHref,

  bannerColor = "#FFFFFF",
  backgroundColor = "#F7F7F7",
  onChangeBannerColor,
  onChangeBackgroundColor,

  profileImageUrl,
  onChangeProfileImage,

  businessName = "Business Name",
  displayName = "Your Name",
  onChangeBusinessName,
  onChangeDisplayName,

  showAddLink = true,
  onAddLinkClick,

  showMerchTag = true,
  onMerchClick,

  previousVends = ["Vended Event 2026"],
  onChangePreviousVends,

  locationText = "City, State",
  email = "myemailaddress@konfolio.com",
  onChangeLocationText,
  onChangeEmail,

  publishLabel = "Publish",
  onPublish,
  onOpenPreview,
}: Props) {
  // ----- local editable state -----
  const [localBusiness, setLocalBusiness] = useState(businessName)
  const [localDisplay, setLocalDisplay] = useState(displayName)
  const [localLocation, setLocalLocation] = useState(locationText)
  const [localEmail, setLocalEmail] = useState(email)

  // Previous vends as array (max 4)
  const [localPrevVends, setLocalPrevVends] = useState<string[]>(
    (previousVends ?? []).slice(0, 4)
  )
  const [newVend, setNewVend] = useState("")

  useEffect(() => setLocalBusiness(businessName), [businessName])
  useEffect(() => setLocalDisplay(displayName), [displayName])
  useEffect(() => setLocalLocation(locationText), [locationText])
  useEffect(() => setLocalEmail(email), [email])
  useEffect(() => setLocalPrevVends((previousVends ?? []).slice(0, 4)), [previousVends])

  // ----- colors -----
  const [localBanner, setLocalBanner] = useState(bannerColor)
  const [localBg, setLocalBg] = useState(backgroundColor)
  useEffect(() => setLocalBanner(bannerColor), [bannerColor])
  useEffect(() => setLocalBg(backgroundColor), [backgroundColor])

  // ----- profile image upload -----
  const inputRef = useRef<HTMLInputElement | null>(null)
  const [localImgUrl, setLocalImgUrl] = useState(profileImageUrl || "")
  const objectUrls = useRef<string[]>([])
  useEffect(() => setLocalImgUrl(profileImageUrl || ""), [profileImageUrl])

  useEffect(() => {
    return () => {
      objectUrls.current.forEach((u) => URL.revokeObjectURL(u))
      objectUrls.current = []
    }
  }, [])

  const openPicker = () => inputRef.current?.click()

  const handleFile = (file: File) => {
    if (!file.type.startsWith("image/")) return
    const url = URL.createObjectURL(file)
    objectUrls.current.push(url)
    setLocalImgUrl(url)
    onChangeProfileImage?.(file, url)
  }

  const onInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    handleFile(file)
    e.target.value = ""
  }

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    const file = e.dataTransfer.files?.[0]
    if (!file) return
    handleFile(file)
  }

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
  }

  const addVend = (raw: string) => {
    const text = (raw || "").trim()
    if (!text) return
    setLocalPrevVends((prev) => {
      if (prev.length >= 4) return prev
      const next = [...prev, text].slice(0, 4)
      onChangePreviousVends?.(next)
      return next
    })
    setNewVend("")
  }

  const parsedPrevVends = useMemo(
    () => localPrevVends.map(parseEventLine),
    [localPrevVends]
  )

  const locationSize = Math.max(localLocation.length || 0, 8)

  return (
    <aside
      className="w-[316px] h-[982px] px-[20px] py-[40px] flex flex-col items-center gap-[10px]"
      style={{ backgroundColor: localBanner }}
    >
      {/* TOP ROW */}
      <div className="relative w-[276px] h-[36px] flex items-center justify-center gap-[40px]">
        <div className="absolute left-0 top-1/2 -translate-y-1/2">
          <ArrowLeft href={backHref} className="w-[30px] h-[30px]" />
        </div>

        {/* Color Field */}
        <div className="flex items-center justify-end gap-[5px] w-[98px] h-[36px]">
          <div className="w-[16px] h-[16px] flex items-center justify-center text-[#A5A5A5]">
            <BrushIcon className="w-[16px] h-[16px]" />
          </div>

          {/* Sidebar color (circle) */}
          <label className="w-[36px] h-[36px] rounded-full border border-[rgba(165,165,165,0.5)] bg-white cursor-pointer relative overflow-hidden">
            <span className="absolute inset-0" style={{ backgroundColor: localBanner }} />
            <input
              type="color"
              className="absolute inset-0 opacity-0 cursor-pointer"
              value={localBanner}
              onChange={(e) => {
                setLocalBanner(e.target.value)
                onChangeBannerColor?.(e.target.value)
              }}
              aria-label="Sidebar color"
            />
          </label>

          {/* Background color (circle) */}
          <label className="w-[36px] h-[36px] rounded-full border border-[rgba(165,165,165,0.5)] cursor-pointer relative overflow-hidden">
            <span className="absolute inset-0" style={{ backgroundColor: localBg }} />
            <input
              type="color"
              className="absolute inset-0 opacity-0 cursor-pointer"
              value={localBg}
              onChange={(e) => {
                setLocalBg(e.target.value)
                onChangeBackgroundColor?.(e.target.value)
              }}
              aria-label="Background color"
            />
          </label>
        </div>
      </div>

      {/* MIDDLE */}
      <div className="w-[276px] flex-1 flex flex-col items-center justify-center gap-[30px]">
        {/* Profile picture */}
        <div
          className="relative w-[189px] h-[189px] bg-white border border-[#A5A5A5] border-[0.5px] rounded-[15px] overflow-hidden"
          onDrop={onDrop}
          onDragOver={onDragOver}
        >
          <input ref={inputRef} type="file" accept="image/*" className="hidden" onChange={onInputChange} />

          <button type="button" className="absolute inset-0" aria-label="Upload profile image" onClick={openPicker}>
            <span className="sr-only">Upload</span>
          </button>

          {localImgUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={localImgUrl}
              alt=""
              className="absolute inset-0 w-full h-full object-cover pointer-events-none"
              draggable={false}
            />
          ) : null}

          {!localImgUrl && (
            <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center gap-[5px]">
              <div className="w-[52px] h-[52px] flex items-center justify-center text-[#A5A5A5] [&_path]:stroke-[#A5A5A5] [&_path]:fill-[#A5A5A5]">
                <ImageIcon />
              </div>
              <p className="m-0 w-[100px] font-inter font-normal text-[11px] leading-[13px] text-center text-[#A5A5A5]">
                Drop image here or click to open files
              </p>
            </div>
          )}
        </div>

        {/* Names */}
        <div className="w-[276px] flex flex-col items-center gap-[12px]">
          <input
            value={localBusiness}
            onChange={(e) => {
              setLocalBusiness(e.target.value)
              onChangeBusinessName?.(e.target.value)
            }}
            placeholder="Business Name"
            className="w-full text-center font-inter font-normal text-[22px] leading-[140%] text-[#A5A5A5] placeholder:text-[#A5A5A5] bg-transparent outline-none"
          />

          <input
            value={localDisplay}
            onChange={(e) => {
              setLocalDisplay(e.target.value)
              onChangeDisplayName?.(e.target.value)
            }}
            placeholder="Your Name"
            className="w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[rgba(165,165,165,0.5)] placeholder:text-[rgba(165,165,165,0.5)] bg-transparent outline-none"
          />
        </div>

        {/* Social medias row (LinkIcon) */}
        <div className="w-[276px] h-[24px] flex items-center justify-center gap-[10px]">
          {showAddLink ? (
            <button
              type="button"
              onClick={onAddLinkClick}
              className="w-[160px] h-[24px] flex items-center justify-center gap-[10px]"
              aria-label="Add link"
            >
              <div className="w-[24px] h-[24px] flex items-center justify-center text-[#A5A5A5]">
                <LinkIcon className="w-[24px] h-[24px]" />
              </div>
            </button>
          ) : null}
        </div>

        {/* Merch tag */}
        {showMerchTag ? (
          <div className="w-[276px] flex justify-center" onClick={onMerchClick}>
            <Tag
              label="Merch"
              showPlus
              className="
                border-[#A5A5A5]/100
                text-[#A5A5A5]
                [&_span]:text-[#A5A5A5]
                [&_svg]:text-[#A5A5A5]
                cursor-pointer
              "
            />
          </div>
        ) : null}

        {/* Previous vends */}
        <div className="w-[276px] flex flex-col items-center gap-[12px]">
          <p className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
            Previous Vends
          </p>

          {/* Existing events (max 4) */}
          <div className="w-full flex flex-col items-center gap-[6px]">
            {parsedPrevVends.map((ev, i) => (
              <div
                key={`${ev.title}-${ev.year ?? ""}-${i}`}
                className="w-full flex items-baseline justify-center gap-[6px]"
              >
                <span className="font-inter font-normal text-[15px] leading-[140%] text-[#262626]">
                  {ev.title || ""}
                </span>

                {ev.year ? (
                  <span className="font-inter italic font-normal text-[12px] leading-[140%] text-[#A5A5A5]">
                    {ev.year}
                  </span>
                ) : null}
              </div>
            ))}
          </div>

          {/* Add new event row (plus + input) */}
          {localPrevVends.length < 4 ? (
            <div className="w-full flex flex-col items-center gap-[8px]">
              <button
                type="button"
                aria-label="Add previous vend"
                className="flex items-center justify-center text-[#A5A5A5]"
                onClick={() => {
                  // focus input
                  const el = document.getElementById("prev-vend-input")
                  ;(el as HTMLInputElement | null)?.focus()
                }}
              >
                <span className="w-[14px] h-[14px] flex items-center justify-center [&_path]:fill-[#A5A5A5] [&_path]:stroke-[#A5A5A5]">
                  <PlusIcon />
                </span>
              </button>

              <input
                id="prev-vend-input"
                value={newVend}
                onChange={(e) => setNewVend(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    e.preventDefault()
                    addVend(newVend)
                  }
                }}
                onBlur={() => {
                  // optional: add on blur if they typed something
                  if (newVend.trim()) addVend(newVend)
                }}
                placeholder="Add an event"
                className="
                  w-full
                  text-center
                  font-inter font-normal
                  text-[15px] leading-[140%]
                  text-[#262626]
                  placeholder:text-[#D3D3D3]
                  bg-transparent
                  outline-none
                "
              />
            </div>
          ) : null}
        </div>

        {/* Location + email */}
        <div className="w-[276px] flex flex-col items-center gap-[12px]">
          {/* Location row */}
          <div className="flex justify-center">
            <div className="inline-flex items-center gap-[5px]">
              <div className="w-[12px] h-[12px] flex items-center justify-center text-[#A5A5A5]">
                <LocationIcon className="w-[12px] h-[12px]" />
              </div>

              <input
                value={localLocation}
                onChange={(e) => {
                  setLocalLocation(e.target.value)
                  onChangeLocationText?.(e.target.value)
                }}
                placeholder="City, State"
                size={locationSize}
                className="
                  w-auto
                  text-center
                  font-inter font-normal
                  text-[15px] leading-[140%]
                  text-[#A5A5A5]
                  placeholder:text-[#A5A5A5]
                  bg-transparent
                  outline-none
                "
              />
            </div>
          </div>

          <input
            value={localEmail}
            onChange={(e) => {
              setLocalEmail(e.target.value)
              onChangeEmail?.(e.target.value)
            }}
            placeholder="myemailaddress@konfolio.com"
            className="
              w-full
              text-center
              font-inter font-normal
              text-[15px] leading-[140%]
              text-[#A5A5A5]
              placeholder:text-[#A5A5A5]
              bg-transparent
              outline-none
            "
          />
        </div>
      </div>

      {/* BOTTOM */}
      <div className="w-[276px] h-[30px] flex items-center justify-center gap-[10px]">
        <SecondaryButton onClick={onPublish}>{publishLabel}</SecondaryButton>

        <button
          type="button"
          aria-label="Open preview"
          onClick={onOpenPreview}
          className="w-[30px] h-[30px] bg-white border border-[#262626] rounded-full flex items-center justify-center"
        >
          <OpenTabIcon className="w-[16px] h-[16px] [&_path]:stroke-[#262626]" />
        </button>
      </div>
    </aside>
  )
}
